(()=>{const query=document.querySelector('#food-search'),area=document.querySelector('#area'),delivery=document.querySelector('#delivery'),cards=[...document.querySelectorAll('.product')],categories=[...document.querySelectorAll('[data-category]')];let category='todos';const norm=t=>t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');function update(){let count=0;for(const card of cards){const match=norm(card.dataset.search).includes(norm(query.value.trim()))&&(category==='todos'||norm(card.dataset.food)===norm(category))&&(area.value==='todos'||card.dataset.area===area.value)&&(delivery.value==='todos'||card.dataset.delivery===delivery.value);card.hidden=!match;if(match)count++}document.querySelector('#count').textContent=count+' '+(count===1?'propuesta':'propuestas');document.querySelector('#empty').hidden=count!==0}function reset(){query.value='';area.value='todos';delivery.value='todos';category='todos';categories.forEach(b=>{const active=b.dataset.category===category;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});update()}query.addEventListener('input',update);area.addEventListener('change',update);delivery.addEventListener('change',update);document.querySelector('#search-form').addEventListener('submit',e=>{e.preventDefault();update()});categories.forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;categories.forEach(b=>{const active=b===button;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});update()}));document.querySelector('#clear').addEventListener('click',reset);document.querySelector('#reset-empty').addEventListener('click',reset);const dialog=document.querySelector('#detail');document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>dialog.showModal()));document.querySelector('#close-detail').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});update()})();
// TequeGo: WhatsApp móvil o WhatsApp Web en computadora.
(()=>{const mobile=navigator.userAgentData?.mobile??(/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||(/Macintosh/i.test(navigator.userAgent)&&navigator.maxTouchPoints>1));if(!mobile)document.querySelectorAll('a.tequego-whatsapp').forEach(link=>{const current=new URL(link.href);const target=new URL('https://web.whatsapp.com/send');target.searchParams.set('phone',current.pathname.slice(1));target.searchParams.set('text',current.searchParams.get('text'));link.href=target.href})})();
